script:
frappe.ui.form.on("Attendance List", {
	setup: function(frm) {
		frm.set_query("annee", function() {
			return {
				filters: [
					["Attendance List","annee", "in", ["annee"]]
				]
			}
		});
	}
});

frappe.ui.form.on('Additional Salary', {
    employee: function(frm) {
        let value = 0;

        if (frm.doc.employment_type === 'Nationaux') {
            value = 0;
        } else {
            value = 1;
        }

        frm.set_query('salary_component', function() {
            return {
                filters: [
                    ['is_variable_score', '=', 1],
                    ['is_expat', '=', value]
                ]
            };
        });
    }
});

frappe.ui.form.on('Attendance', {
    employee: function(frm) {

		frm.set_query('shift', function() {
			return {
				filters: [
					['is_shift_leave', '=', 0]
				]
			};
		});

		if (frm.doc.shift && frm.doc.is_shift_leave === 0) {
            frm.set_value('shift', null);
            frappe.msgprint(__('Le champ Shift a été réinitialisé car il répond aux critères.'));
        }

    }

})

frappe.ui.form.on('Preparation Provision Decompte', {
    refresh(frm) {
        // Code de rafraîchissement si nécessaire
    },
    
    période_décompte: function(frm) {
            // Vérifier si une période de décompte est sélectionnée
            if (frm.doc.période_décompte) {
                frappe.call({
                    method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.provision.liste_employees_non_decomptes",
                    args: {
                        'period': frm.doc.période_décompte
                    },
                    callback: function(response) {
                        const data = response.message;
                        if (data && data.length > 0) {
                            // Utiliser la liste des noms d'employés renvoyée
                            const excludedEmployees = data;
                             //frappe.msgprint(__('Ok ' + data));
                            // Filtrer pour exclure les employés déjà décomptés
                            frm.set_query('employee', function() {
                                return {
                                    filters: [
                                        ['Employee', 'name', 'in', excludedEmployees]
                                    ]
                                };
                            });
                        } else {
                            frappe.msgprint(__('Aucun employé à exclure pour cette période.'));
                        }
                    },
                    error: function(err) {
                        console.error('Erreur lors de la récupération:', err);
                        frappe.msgprint(__('Erreur lors de la récupération des employés: ' + err));
                    }
                });
            } else {
                frappe.msgprint(__('Veuillez sélectionner une période avant de choisir un employé.'));
            }
        }

});

frappe.ui.form.on('Rapports Op', {
	refresh(frm) {
		frm.add_custom_button(
			__("Imprimer"),
			function () {
				if(frm.is_new()) return;
				let d = new frappe.ui.Dialog({
					title: 'Mise à jour Provision',
					fields: [
						{
							label: 'Fiscal Year',
							fieldname: 'fiscal_year',
							fieldtype: 'Link',
							options: "Fiscal Year",
							on_change : () => {
							    frappe.db.get_doc("Fiscal Year", cur_dialog.get_value('fiscal_year')).then(r => {
    						    cur_dialog.set_value('debut',r.start_date);
    						    cur_dialog.set_value('fin',r.end_date);
    						});
							}
						}
					],
					primary_action_label: __('Mettre à jour'),
					primary_action(values) {

					    frappe.call({
            			method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.provision.update_provision_details",
            			args: {
            				fiscal_year: values.fiscal_year,
            				emp_name: frm.doc.name,
            			},
            			callback: function (r) {
            				if (r) {
                                frappe.msgprint("Provision Mise à Jour");
                            }
            			}
            		});

						d.hide();
					}
				});
				d.show();
			}
		);
	}
})

frappe.ui.form.on('Updating Attendance', {
	refresh(frm) {
	    $('.primary-action').prop('hidden', true);

        var button = frm.fields_dict.get_attendances.$wrapper.find('button');
        button.addClass('btn btn-primary text-white custom-button');

        // Ajouter des styles personnalisés pour l'état de survol
        $('head').append(`
            <style>
                .custom-button:hover {
                    background-color: #f1f1f1 !important; /* Couleur de fond blanc foncé au survol */
                    color: #007bff !important; /* Couleur du texte bleu au survol */
                }
            </style>
        `);

    	var button = frm.add_custom_button(__('Update Attendance'), function() {
            let fiend = 0; // Initialise le compteur à 0
            if (!frm.doc.employee || frm.doc.employee.trim() === '') {
                frappe.throw({
                    title: __('Erreur'),
                    indicator: 'red',
                    message: __('Le champ Employee est requis.')
                });
            } else {
                let payroll_period = frm.doc.payroll_period;
                let employee = frm.doc.employee;

                let processItem = function(item) {
                    return new Promise((resolve) => {
                        console.log(`employee : ${employee}`);
                        console.log(`Date: ${item.date}`);
                        console.log(`status: ${item.status}`);
                        console.log(`shift: ${item.shift}`);

                        frappe.call({
                            method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.updates_attendances.updating_attendance_save",
                            args: {
                                Employee: employee,
                                date: item.date,
                                present: item.status,
                                shift: item.shift,
                            },
                            callback: function(response) {
                                if (response.message && response.message.length > 0) {
                                    frappe.call({
                                        method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.updates_attendances.updating_attendance_check",
                                        args: {
                                            Employee: employee,
                                            date: item.date,
                                            present: item.status,
                                        },
                                        callback: function(response) {
                                            const data = response.message;
                                            if (!data || data.length === 0) {
                                                let doctype = "Attendance";
                                                let Attend = frappe.model.get_new_doc(doctype);

                                                Attend.employee = employee;
                                                Attend.attendance_date = item.date;
                                                Attend.company = frm.doc.societe;
                                                Attend.shift = item.shift;
                                                Attend.status = item.status;

                                                frappe.db.insert(Attend).then(function(doc) {
                                                    if (doc) {
                                                        frappe.call({
                                                            method: "frappe.client.submit",
                                                            args: {
                                                                doc: doc
                                                            },
                                                            callback: function(response) {
                                                                if (response.message) {
                                                                    fiend++; // Incrémenter après une soumission réussie
                                                                    console.log(`Code operation: ${fiend}`);
                                                                } else {
                                                                    console.error('Erreur lors de la soumission du document.');
                                                                }
                                                                resolve(); // Toujours résoudre la promesse
                                                            },
                                                            error: function(err) {
                                                                console.error('Erreur lors de la soumission:', err);
                                                                resolve(); // Toujours résoudre la promesse même en cas d'erreur
                                                            }
                                                        });
                                                    } else {
                                                        console.error('Erreur lors de l\'insertion du document.');
                                                        resolve(); // Toujours résoudre la promesse même en cas d'erreur
                                                    }
                                                });
                                            } else {
                                                console.log(`Data already exists, skipping insertion.`);
                                                resolve(); // Rien à insérer, donc on résout la promesse
                                            }
                                        },
                                        error: function(err) {
                                            console.error('Erreur lors de la vérification des codes:', err);
                                            resolve(); // Toujours résoudre la promesse même en cas d'erreur
                                        }
                                    });
                                } else {
                                    console.error("La réponse du serveur est vide ou invalide.");
                                    resolve(); // Toujours résoudre la promesse même si la réponse est invalide
                                }
                            },
                            error: function(err) {
                                console.error('Erreur lors de la mise à jour des codes:', err);
                                resolve(); // Toujours résoudre la promesse même en cas d'erreur
                            }
                        });
                    });
                };

                // Utiliser une boucle asynchrone pour traiter chaque élément séquentiellement
                (async function() {
                    for (let item of frm.doc.details_updating_attendance) {
                        await processItem(item);
                    }

                    console.log(`Résultat OK: ${fiend}`);
                    if (fiend > 0) {
                        let message = (fiend >= 2) ? `${fiend} Enregistrements Modifiés` : `${fiend} Enregistrement Modifié`;
                        frappe.msgprint(__(message));
                    }
                })();
            }
        });




        button.addClass('btn btn-primary text-white custom-update-attendance-btn');

        // Injecter le style personnalisé pour l'état de survol
        $('head').append(`
            <style>
                .custom-update-attendance-btn:hover {
                    background-color: #f1f1f1 !important; /* Couleur de fond blanc foncé au survol */
                    color: #007bff !important; /* Couleur du texte bleu au survol */
                }
            </style>
        `);

	},
	get_attendances: function(frm) {
        // Vérifier si le champ 'societe' est renseigné
        if (!frm.doc.societe) return;

        // Effacer le tableau 'details_updating_attendance'
        frm.clear_table('details_updating_attendance');
        frm.refresh_field('details_updating_attendance'); // Rafraîchir l'affichage

        // Récupérer les valeurs des champs 'payroll_period' et 'employee'
        let payroll_period = frm.doc.payroll_period;
        let employee = frm.doc.employee;

        // Vérifier si le champ 'employee' est renseigné
        if (!employee || employee.trim() === '') {
            frappe.throw({
                title: __('Erreur'),
                indicator: 'red',
                message: __('Le champ Employee est requis.')
            });
        } else {
            // Appeler la méthode pour récupérer les dates de la période de paie
            frappe.call({
                method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.updates_attendances.get_payroll_period_date",
                args: {
                    'employee': employee,
                    'name': payroll_period
                },
                callback: function(r) {
                    console.log(r); // Vérifiez ce qui est renvoyé

                    if (r.message && Array.isArray(r.message)) {
                        console.log(`Pariod: ${payroll_period}`);

                        // Récupérer les valeurs du tableau
                        let my_start = '01/12/1999';
                        let my_end = '01/12/2099';
                        let employment_type = r.message[2]; // Type d'emploi

                        if (employment_type === 'Expatriés') {
                            my_start = r.message[0]; // start_date_exp
                            my_end = r.message[1];   // end_date_exp
                        } else {
                            my_start = r.message[0]; // start_date
                            my_end = r.message[1];   // end_date
                        }

                        console.log(`my_start: ${my_start}`);
                        console.log(`my_end: ${my_end}`);
                        console.log(`r.message.employment_type: ${employment_type}`);

                        // Appeler la méthode pour récupérer les données d'assiduité
                        frappe.call({
                            method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.updates_attendances.get_attendances_data",
                            args: {
                                'employee': employee,
                            },
                            callback: function(response) {
                                const data = response.message;
                                if (data && data.length > 0) {
                                    // Ajouter les données d'assiduité au tableau
                                    data.forEach(function(item) {
                                        frm.add_child('details_updating_attendance', {
                                            'shift': item.shift,
                                            'date': item.attendance_date,
                                            'status': item.status
                                        });
                                    });
                                    frm.refresh_field('details_updating_attendance'); // Rafraîchir l'affichage après ajout des données
                                }
                            },
                            error: function(err) {
                                console.error('Erreur lors de la récupération des codes:', err);
                                frappe.msgprint(__('Erreur: ', [err]));
                            }
                        });
                    } else {
                        frappe.msgprint(__('Aucune donnée valide reçue.'));
                    }
                },
                error: function(err) {
                    console.error('Erreur lors de la récupération des transferts:', err);
                    frappe.msgprint(__('Erreur: ', [err]));
                }
            });
        }
    }


})

frappe.ui.form.on('Init Provision', {
	refresh(frm) {
	    $('.primary-action').prop('hidden', true);

        var button = frm.fields_dict.get_employees.$wrapper.find('button');
        button.addClass('btn btn-primary text-white custom-button');

        // Ajouter des styles personnalisés pour l'état de survol
        $('head').append(`
            <style>
                .custom-button:hover {
                    background-color: #f1f1f1 !important; /* Couleur de fond blanc foncé au survol */
                    color: #007bff !important; /* Couleur du texte bleu au survol */
                }
            </style>
        `);

        var button = frm.add_custom_button(__('Mettre à Jour'), function() {

            if (!frm.doc.fiscal_year) {
                frappe.throw({
                    title: __('Erreur'),
                    indicator: 'red',
                    message: __('Le champ Employee est requis.')
                });
                return;
            }

            // Récupération des données de la table 'details'
            let details = frm.doc.details || [];

            if (details.length === 0) {
                frappe.msgprint(__('Aucune donnée à mettre à jour.'));
                return;
            }

            details.forEach(function(detail) {

                let fiscal_year = frm.doc.fiscal_year
                let find = 0; // Remplacez par votre logique de calcul
                let matricule = detail.employee; // Assurez-vous que 'matricule' est bien l'identifiant
                let ratio = detail.ratio; 
                let conge = detail.conge;
                let ticket = detail.ticket;
                let leave_type = frm.doc.leave_type

                if (matricule) {
                    frappe.call({
                        method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.provision.update_provision_ratio",
                        args: {
                            fiscal_year: fiscal_year,
                            emp_name: matricule,
                            ratio : ratio,
                            conge : conge,
                            ticket : ticket,
                            leave_type : leave_type
                        },
                        callback: function(response) {
                            if (response.message) {
                                find = find + 1;
                                //frappe.msgprint(__('Mise à jour réussie.', response.message));
                            }
                        }
                    });
                } else {
                    console.error('Matricule manquant pour le détail:', detail);
                    frappe.msgprint(__('Matricule manquant pour le détail.'));
                }

            });

            (async function() {
                for (let item of frm.doc.details) {
                    await processItem(item);
                }

                console.log(`Résultat OK: ${fiend}`);
                if (fiend > 0) {
                    let message = (fiend >= 2) ? `${fiend} Enregistrements Modifiés` : `${fiend} Enregistrement Modifié`;
                    frappe.msgprint(__(message));
                }
            })();

        });

        button.addClass('btn btn-primary text-white custom-update-attendance-btn');

        // Injecter le style personnalisé pour l'état de survol
        $('head').append(`
            <style>
                .custom-update-attendance-btn:hover {
                    background-color: #f1f1f1 !important; /* Couleur de fond blanc foncé au survol */
                    color: #007bff !important; /* Couleur du texte bleu au survol */
                }
            </style>
        `);

        },
    get_employees: function(frm) {
        // Effacer le tableau 'details'
        frm.clear_table('details');
        frm.refresh_field('details'); // Rafraîchir l'affichage

        // Récupérer les valeurs des champs 'fiscal_year' et 'employee'
        let fiscal_year = frm.doc.fiscal_year;
        let employee = frm.doc.leave_type;

        // Vérifier si l'employé est défini
        if (!employee) {
            frappe.msgprint(__('Veuillez sélectionner un employé.'));
            return; // Arrêter l'exécution si aucun employé n'est sélectionné
        }

        // Appel pour récupérer les informations des employés
        frappe.call({
            method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.provision.get_provision_init",
            args: {
                fiscal_year: fiscal_year,
                employee: employee
            },
            callback: function(response) {
                console.log('Response:', response); // Vérifiez la réponse
                const data = response.message;

                // Vérifier si des données ont été récupérées
                if (data && data.length > 0) {
                    // Ajouter les données d'assiduité au tableau
                    data.forEach(function(item) {
                        // Supposons que les indices suivants correspondent aux valeurs que vous souhaitez extraire
                        const matricule = item[0]; // Par exemple, le matricule pourrait être à l'index 0
                        const ratio = item[8]; // Par exemple, le ratio pourrait être à l'index 9
                        const conge = item[9]; // Par exemple, le congé pourrait être à l'index 10
                        const ticket = item[15]; // Par exemple, le ratio pourrait être à l'index 9
                        const gratification = item[14]; // Par exemple, le congé pourrait être à l'index 10
                        const bonus = item[16]; // Par exemple, le ratio pourrait être à l'index 9
                        //frappe.msgprint(__('Mise à jour réussie.', item));
                        frm.add_child('details', {
                            'employee': matricule,
                            'ratio': ratio,
                            'conge': conge,
                            'bonus': bonus,
                            'ticket': ticket,
                            'gratification': gratification
                        });
                    });
                    frm.refresh_field('details'); // Rafraîchir l'affichage après ajout des données
                } else {
                    frappe.msgprint(__('Aucune donnée trouvée pour cet employé.'));
                }
            },
            error: function(err) {
                console.error('Erreur lors de la récupération des codes:', err);
                frappe.msgprint(__('Erreur: ', [err]));
            }
        });
    }



})

