frappe.ui.form.on('Employee', {
	refresh(frm) {
		frm.add_custom_button(
			__("Provision"),
			function () {
				if (frm.is_new()) return;
				let d = new frappe.ui.Dialog({
					title: 'Mise à jour Provision',
					fields: [
						{
							label: 'Fiscal Year',
							fieldname: 'fiscal_year',
							fieldtype: 'Link',
							options: "Fiscal Year",
							on_change: () => {
								frappe.db.get_doc("Fiscal Year", cur_dialog.get_value('fiscal_year')).then(r => {
									cur_dialog.set_value('debut', r.start_date);
									cur_dialog.set_value('fin', r.end_date);
								});
							}
						},
						{
							label: 'Leave Type',
							fieldname: 'leave_type',
							fieldtype: 'Link',
							options: 'Leave Type',
							get_query: () => {
								return {
									filters: {
										'is_on_provision': 1
									}
								};
							}
						}
					],
					primary_action_label: __('Mettre à jour'),
					primary_action(values) {
						frappe.call({
							method: "fleuve_congo_custom.fleuve_congo_custom.doctype.provision.provision.update_provision_details",
							args: {
								fiscal_year: values.fiscal_year,
								leave_type: values.leave_type,
								emp_name: frm.doc.name,
								employment_type:frm.doc.employment_type,
							},
							callback: function (r) {
								if (r) {
									frappe.msgprint("Provision Mise à Jour");
								}
							}
						});
						d.hide();
					}
				});
				d.show();
			}
		);
	}
});
